-- Relational schema for the "jdbc" profile.
--
-- The six catalog tables are the legacy Cloudscape DDL from PopulateSQL.xml with two changes:
--   * char(n) ids became varchar(n), so no more .trim() on every read
--   * item.seq makes the old implicit row order explicit
-- The legacy customer data was spread over six CMP tables generated by the J2EE RI deploy tool;
-- it is a single table here because it was always read and written as one unit.

create table if not exists category (
    catid varchar(10) not null primary key
);

create table if not exists category_details (
    catid  varchar(10)  not null references category (catid),
    locale varchar(10)  not null,
    name   varchar(80)  not null,
    image  varchar(255),
    descn  varchar(255),
    primary key (catid, locale)
);

create table if not exists product (
    productid varchar(10) not null primary key,
    catid     varchar(10) not null references category (catid)
);

create table if not exists product_details (
    productid varchar(10)  not null references product (productid),
    locale    varchar(10)  not null,
    name      varchar(80)  not null,
    image     varchar(255),
    descn     varchar(255),
    primary key (productid, locale)
);

create table if not exists item (
    itemid    varchar(10) not null primary key,
    productid varchar(10) not null references product (productid),
    seq       int         not null
);

create table if not exists item_details (
    itemid    varchar(10)    not null references item (itemid),
    locale    varchar(10)    not null,
    listprice decimal(10, 2) not null,
    unitcost  decimal(10, 2) not null,
    image     varchar(255)   not null,
    descn     varchar(255)   not null,
    attr1     varchar(80),
    attr2     varchar(80),
    attr3     varchar(80),
    attr4     varchar(80),
    attr5     varchar(80),
    primary key (itemid, locale)
);

create table if not exists signon (
    username      varchar(25)  not null primary key,
    password_hash varchar(100) not null
);

create table if not exists customer (
    userid             varchar(25) not null primary key,
    status             varchar(10) not null,
    given_name         varchar(30),
    family_name        varchar(30),
    street1            varchar(70),
    street2            varchar(70),
    city               varchar(70),
    state              varchar(70),
    zip                varchar(12),
    country            varchar(70),
    email              varchar(70),
    phone              varchar(70),
    card_number        varchar(30),
    card_type          varchar(30),
    card_expiry        varchar(10),
    preferred_language varchar(10),
    favorite_category  varchar(10),
    mylist_on          boolean     not null,
    banners_on         boolean     not null
);

create table if not exists purchase_order (
    orderid      varchar(20)    not null primary key,
    userid       varchar(25),
    email        varchar(70),
    order_date   timestamp      not null,
    locale       varchar(10)    not null,
    card_type    varchar(30),
    card_masked  varchar(30),
    card_expiry  varchar(10),
    total_price  decimal(12, 2) not null,
    status       varchar(20)    not null
);

create table if not exists order_contact (
    orderid     varchar(20) not null references purchase_order (orderid),
    kind        varchar(4)  not null, -- BILL or SHIP
    given_name  varchar(30),
    family_name varchar(30),
    street1     varchar(70),
    street2     varchar(70),
    city        varchar(70),
    state       varchar(70),
    zip         varchar(12),
    country     varchar(70),
    email       varchar(70),
    phone       varchar(70),
    primary key (orderid, kind)
);

create table if not exists line_item (
    orderid    varchar(20)    not null references purchase_order (orderid),
    linenum    int            not null,
    catid      varchar(10),
    productid  varchar(10),
    itemid     varchar(10)    not null,
    quantity   int            not null,
    unitprice  decimal(10, 2) not null,
    primary key (orderid, linenum)
);

create table if not exists counter (
    name  varchar(20) not null primary key,
    counter_value bigint not null
);
